#!/usr/bin/env python3
"""Portava — REAL in-app post share (post_card), replacing ShareSheet's fake
handleInAppShare. Adds PostCardMessage renderer + wires it into the Telegraph
thread. Applies to BOTH trees. Idempotent, self-checking, drift-safe:
 - PostCardMessage.tsx: written if absent/different (new file, safe).
 - ShareSheet.tsx: rewritten ONLY if the fake-share stub is still present;
   if the file diverged upstream it is REPORTED, never clobbered.
 - messages/[id].tsx: 3 exact-anchor edits, each skipped if already applied.
Run from ~/workspace:  python3 sharesheet_pack.py
"""
import base64, pathlib, sys

ROOT  = sys.argv[1] if len(sys.argv) > 1 else '.'
TREES = ['artifacts/travel-buddy/', 'travel-buddy-standalone/']
log = []

POSTCARD_B64  = ''
SHARESHEET_B64 = ''

def write_new_file(rel, b64):
    content = base64.b64decode(b64).decode()
    for tree in TREES:
        p = pathlib.Path(ROOT) / (tree + rel)
        if not p.parent.exists():
            log.append('skip no-dir  ' + tree + rel); continue
        if p.exists() and p.read_text() == content:
            log.append('already      ' + tree + rel); continue
        p.write_text(content); log.append('WROTE        ' + tree + rel)

def rewrite_sharesheet(rel, b64):
    content = base64.b64decode(b64).decode()
    for tree in TREES:
        p = pathlib.Path(ROOT) / (tree + rel)
        if not p.exists():
            log.append('skip missing ' + tree + rel); continue
        s = p.read_text()
        if "subtype: 'post_card'" in s:
            log.append('already      ' + tree + rel); continue
        if 'Shared to ${featureName}' not in s:
            log.append('NEEDS A LOOK (fake-share anchor gone; not clobbering) ' + tree + rel); continue
        p.write_text(content); log.append('REWROTE      ' + tree + rel)

EDITS = [
    ("import { DiscoveryCardMessage } from '../../src/components/DiscoveryCardMessage';", "import { DiscoveryCardMessage } from '../../src/components/DiscoveryCardMessage';\nimport { PostCardMessage } from '../../src/components/PostCardMessage';", "import { PostCardMessage } from '../../src/components/PostCardMessage';", 'import'),
    ("  // Compass card — shared from the Ask Compass tray\n  if (item.msgType === 'system' && item.subtype === 'compass_card') {", "  // Shared post card — sent from a post's ShareSheet\n  if (item.msgType === 'system' && item.subtype === 'post_card') {\n    return (\n      <Pressable onLongPress={onLongPress} delayLongPress={300}>\n        <PostCardMessage body={item.body ?? ''} mine={mine} />\n      </Pressable>\n    );\n  }\n\n  // Compass card — shared from the Ask Compass tray\n  if (item.msgType === 'system' && item.subtype === 'compass_card') {", "item.subtype === 'post_card'", 'render-branch'),
    ("if (m.msgType === 'system' && m.subtype !== 'discovery_card' && m.subtype !== 'compass_card' && !parseMeetupCard(m.body ?? '', m)) {", "if (m.msgType === 'system' && m.subtype !== 'discovery_card' && m.subtype !== 'compass_card' && m.subtype !== 'post_card' && !parseMeetupCard(m.body ?? '', m)) {", "m.subtype !== 'post_card' && !parseMeetupCard", 'pill-guard'),
]

def anchored_edits(rel):
    for tree in TREES:
        p = pathlib.Path(ROOT) / (tree + rel)
        if not p.exists():
            log.append('skip missing ' + tree + rel); continue
        s = p.read_text(); orig = s; notes = []
        for old, new, mark, tag in EDITS:
            if mark in s:
                continue
            if old not in s:
                notes.append('anchor missing: ' + tag); continue
            if s.count(old) != 1:
                notes.append('anchor not-unique x%d: %s' % (s.count(old), tag)); continue
            s = s.replace(old, new, 1)
        if s != orig:
            p.write_text(s); log.append('PATCHED      ' + tree + rel + ('  ['+'; '.join(notes)+']' if notes else ''))
        elif notes:
            log.append('NEEDS A LOOK ' + tree + rel + '  [' + '; '.join(notes) + ']')
        else:
            log.append('already      ' + tree + rel)

write_new_file('src/components/PostCardMessage.tsx', POSTCARD_B64)
rewrite_sharesheet('src/components/ShareSheet.tsx', SHARESHEET_B64)
anchored_edits('app/messages/[id].tsx')

print('\n'.join(log))
print('done.')
